#!/usr/bin/env python3

def read_file(file_path):
    with open(file_path, 'r') as f:
        return f.read().strip()

def decrypt(encrypted_bytes, key_bytes):
    """Decrypt using XOR with key"""
    result = bytearray()
    for i in range(len(encrypted_bytes)):
        result.append(encrypted_bytes[i] ^ key_bytes[i % len(key_bytes)])
    return bytes(result)

def encrypt(plaintext, key_bytes):
    """Encrypt using XOR with key"""
    return decrypt(plaintext.encode(), key_bytes)

def bytes_to_hex(b):
    return ''.join(f'{byte:02x}' for byte in b)

def hex_to_bytes(hex_str):
    return bytes.fromhex(hex_str)

def clean_password(password):
    """Remove any non-printable characters"""
    return ''.join(chr(c) if 32 <= c <= 126 else '' for c in password)

def main():
    # Read the leaked password and encrypted passwords
    leaked_password_path = "/home/ctfplayer/ctf_files/leaked_password.txt"
    encrypted_passwords_path = "/home/ctfplayer/ctf_files/encrypted_passwords.txt"

    known_password = read_file(leaked_password_path)
    print(f"Leaked password: {known_password}")

    with open(encrypted_passwords_path, 'rb') as f:
        encrypted_data = f.read()

    # Parse the encrypted passwords (assuming they're stored one after another)
    encrypted_passwords = []
    i = 0
    while i < len(encrypted_data):
        # Each encrypted password likely has a fixed length
        # The exact length might be different, but let's try different sizes
        for length in range(15, 30):  # Try different possible lengths
            if i + length <= len(encrypted_data):
                encrypted_passwords.append(encrypted_data[i:i+length])
        i += 1

    print(f"Found {len(encrypted_passwords)} potential encrypted passwords")

    # Find the encrypted version of our known password
    known_password_bytes = known_password.encode()
    candidates = []

    for encrypted in encrypted_passwords:
        if len(encrypted) >= len(known_password_bytes):
            # Try to recover the key by XORing
            potential_key = decrypt(encrypted[:len(known_password_bytes)], known_password_bytes)

            # Test if this key works by re-encrypting
            test_encrypted = encrypt(known_password, potential_key)

            if test_encrypted == encrypted[:len(test_encrypted)]:
                candidates.append((encrypted, potential_key))

    print(f"Found {len(candidates)} potential matches for the leaked password")

    # For each candidate, decrypt all passwords and look for the admin password
    for candidate_encrypted, candidate_key in candidates:
        print(f"\nCandidate key: {bytes_to_hex(candidate_key)}")
        print(f"Key as ASCII (where printable): {repr(candidate_key)}")

        # Decrypt all passwords with this key
        for encrypted in encrypted_passwords:
            decrypted = decrypt(encrypted, candidate_key)

            # Look for passwords that might be the admin's
            # Admin password likely doesn't follow Pokemon-Type pattern
            try:
                decrypted_str = decrypted.decode('ascii', errors='replace')
                if not '-' in decrypted_str and len(decrypted_str) >= 5:
                    print(f"Possible admin password: {decrypted_str}")
                    print(f"ASCII bytes: {repr(decrypted)}")
                    print(f"Hex: {bytes_to_hex(decrypted)}")

                    # Clean any non-printable characters
                    clean_pwd = clean_password(decrypted)
                    if clean_pwd:
                        print(f"Cleaned password: {clean_pwd}")
                        print(f"Possible flag: flag{{{clean_pwd}}}")
            except:
                continue

if __name__ == "__main__":
    main()

